// CSS of a Noahs design, generated by the editor's OWN generator (generate-css.js), read at run time from the
// source map shipped with the installed module (assets/js/editor.js.map has sourcesContent). Nothing is copied
// into this kit: the generator always matches the installed Noahs version.
//
// Same sequence as the editor's Save button:  css = await prepareStyles(); css += await prepatePageStyles();
//
// Usage: NOAHS_MODULE_DIR=<module dir> [NOAHS_BASE_URL=… NOAHS_COOKIE=…] \
//          node page-css.js <editor.html> <structure.json> <out.css> <out-page-settings.json>
//   editor.html    HTML of the editor page, fetched with an admin session (carries drupalSettings and the
//                  page settings form).
//   structure.json The saved design (settings column).
const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');

const [, , editorPath, structurePath, cssOut, psOut] = process.argv;
const moduleDir = process.env.NOAHS_MODULE_DIR;
if (!moduleDir) {
  console.error('NOAHS_MODULE_DIR is not set.');
  process.exit(1);
}

function generatorSource() {
  const map = JSON.parse(fs.readFileSync(path.join(moduleDir, 'assets/js/editor.js.map'), 'utf8'));
  const i = map.sources.findIndex((s) => s.endsWith('modules/generate-css.js'));
  if (i < 0 || !map.sourcesContent || !map.sourcesContent[i]) {
    throw new Error('generate-css.js not found in editor.js.map: this Noahs version is not supported by the kit.');
  }
  return map.sourcesContent[i].replace(/export\s+function\s+exportGenerateCss/, 'function exportGenerateCss')
    + '\nwindow.exportGenerateCss = exportGenerateCss;\n';
}

const html = fs.readFileSync(editorPath, 'utf8');
const m = html.match(/<script type="application\/json" data-drupal-selector="drupal-settings-json">([\s\S]*?)<\/script>/);
if (!m) {
  console.error('No drupalSettings in the editor HTML (login failed or wrong URL?).');
  process.exit(1);
}
const w = new JSDOM(html, { runScripts: 'outside-only' }).window;
w.drupalSettings = JSON.parse(m[1]);
const p = w.drupalSettings.path || {};
w.Drupal = {
  url: (route) => (p.baseUrl || '/') + (p.pathPrefix || '') + route,
  t: (str) => str,
};
if (!w.drupalSettings.noahs_items_fields) {
  console.error('drupalSettings has no noahs_items_fields: this is not a Noahs editor page.');
  process.exit(1);
}
w.eval(fs.readFileSync(require.resolve('jquery/dist/jquery.min.js'), 'utf8'));
w.eval(fs.readFileSync(path.join(moduleDir, 'assets/js/builder/libs/serializejson.js'), 'utf8'));
w.eval(generatorSource());

// Background images are resolved with fetch('/noahs-admin/get-media-image/…') relative to the site, with a session.
if (process.env.NOAHS_BASE_URL) {
  w.fetch = (url, opts = {}) => fetch(new URL(url, process.env.NOAHS_BASE_URL), {
    ...opts, headers: { ...(opts.headers || {}), Cookie: process.env.NOAHS_COOKIE || '' },
  }).then(async (r) => ({ ok: r.ok, status: r.status, json: async () => JSON.parse(await r.text()) }));
}
w.exportGenerateCss();
const structure = fs.readFileSync(structurePath, 'utf8');
w.getWidgetStructure = () => structure;

(async () => {
  let css = await w.prepareStyles();
  css += await w.prepatePageStyles();
  const form = w.document.querySelector('#noahs_page_builder_sttings_page_form');
  const pageSettings = {
    page_settings: form ? w.jQuery(form).serializeJSON() : {},
    page_fields: typeof w.prepateFormPageSettings === 'function' ? w.prepateFormPageSettings() : {},
  };
  fs.writeFileSync(cssOut, css);
  fs.writeFileSync(psOut, JSON.stringify(pageSettings));
  console.log(`CSS ${css.length} bytes.`);
})().catch((e) => {
  console.error(e);
  process.exit(1);
});
